function replaceEmojis(text: string, preferredSkinTone: OnyxEntry<number | string> = CONST.EMOJI_DEFAULT_SKIN_TONE, lang: Locale = CONST.LOCALES.DEFAULT): ReplacedEmoji {
    const emojis: Emoji[] = [];
    let newText = text;
    let cursorPosition;

    const emojiNames = newText.match(CONST.REGEX.EMOJI_NAME_CAPTURE);

    if (!emojiNames || emojiNames.length === 0) {
        return {
            text: newText,
            emojis: [],
        };
    }

    const emojisTrie = require<EmojiTrieModule>('./EmojiTrie').default;
    const trie = emojisTrie[lang as SupportedLanguage];

    emojiNames.forEach((emojiName) => {
        const bareEmojiName = emojiName.slice(1, -1);

        if (trie) {
            const nodes = trie.getAllMatchingWords(bareEmojiName, 1);
            if (nodes.length > 0 && nodes[0].name === bareEmojiName) {
                const emoji = {code: nodes[0].metaData.code ?? '', name: nodes[0].name, types: nodes[0].metaData.types};
                emojis.push(emoji);

                const emojiCode = getPreferredEmojiCode(emoji, preferredSkinTone);

                const newTextWithEmoji = newText.replace(emojiName, emojiCode);

                if (newTextWithEmoji !== newText) {
                    const emojiLength = emojiCode.length;
                    const emojiNameLength = emojiName.length;

                    const emojiPosition = newText.indexOf(emojiName);

                    cursorPosition = emojiPosition + emojiLength;

                    newText = newTextWithEmoji;
                }
            }
        }
    });

    return {
        text: newText,
        emojis,
        cursorPosition,
    };
}

